// DeckChek Mobile service worker: precaches every file of the app so each screen works offline (AC-2).
// The BUILD block is generated by tools/build-mobile.mjs from the hashes of all files, so any change to any file
// gives a new cache name. A new worker waits until the person taps "Update now" (the page then sends skip-waiting).

/* BUILD:START (generated by tools/build-mobile.mjs, do not edit) */
const BUILD = '4fa869ba0c14';
const PRECACHE = [
  "./",
  "./app.js",
  "./icons/icon-192.png",
  "./icons/icon-512.png",
  "./icons/icon-maskable-512.png",
  "./lib/audio.js",
  "./lib/capture-worklet.js",
  "./lib/export.js",
  "./lib/motion.js",
  "./lib/qr.js",
  "./lib/speed.js",
  "./lib/spl.js",
  "./lib/store.js",
  "./lib/strobe.js",
  "./lib/ui.js",
  "./lib/vibration.js",
  "./manifest.webmanifest",
  "./screens/results.js",
  "./screens/speed.js",
  "./screens/spl.js",
  "./screens/strobe.js",
  "./screens/vibration.js",
  "./styles.css",
  "./vendor/VERSION",
  "./vendor/advanced.js",
  "./vendor/calibration.js",
  "./vendor/canonical-json.js",
  "./vendor/core.js",
  "./vendor/phone-run.js",
  "./vendor/qr.js",
  "./vendor/sha256.js",
  "./index.html"
];
/* BUILD:END */

const CACHE = `deckchek-mobile-${BUILD}`;

self.addEventListener('install', event => {
  event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(PRECACHE)));
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) if (key.startsWith('deckchek-mobile-') && key !== CACHE) await caches.delete(key);
    await self.clients.claim();
  })());
});

self.addEventListener('message', event => {
  if (event.data && event.data.type === 'skip-waiting') self.skipWaiting();
});

self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return; // never touch other origins: nothing is fetched from elsewhere
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const hit = await cache.match(request, { ignoreSearch: true });
    if (hit) return hit;
    if (request.mode === 'navigate') {
      const shell = await cache.match('./index.html');
      if (shell) return shell;
    }
    return fetch(request);
  })());
});
